declare(strict_types=1);

namespace Schoolbox\APIConfig\Authorizer\Rule;

use Alaress\Authorizer\Failure\Unauthenticated;
use Alaress\Authorizer\Rule\IAuthorizationRule;
use Psr\Log\LoggerInterface;
use Schoolbox\API\Token\JwtParser\InstanceRegistryIssued;
use Schoolbox\API\Token\JwtParser\Exception\Rejected;
use Schoolbox\User;

/**
 * Authorization rule to check if the request has a valid Instance Registry JWT token.
 */
class HasValidInstanceRegistryToken implements IAuthorizationRule
{
    private InstanceRegistryIssued $jwtParser;
    private LoggerInterface $logger;

    public function __construct(
        InstanceRegistryIssued $jwtParser,
        LoggerInterface $logger
    ) {
        $this->jwtParser = $jwtParser;
        $this->logger = $logger;
    }

    /**
     * @inheritdoc
     */
    public function authorize(array $params = array(), ?User $user = null): void
    {
        // Extract JWT from Authorization header
        $authHeader = $this->getAuthorizationHeader();
        if (empty($authHeader)) {
            $this->logger->debug('No Authorization header found');
            throw new Unauthenticated();
        }

        // Check if it's a Bearer token
        if (!preg_match('/^Bearer\s+(.+)$/i', $authHeader, $matches)) {
            $this->logger->debug('Authorization header is not a Bearer token');
            throw new Unauthenticated();
        }

        $jwt = $matches[1];

        try {
            // Check if the JWT parser accepts this token
            if (!$this->jwtParser->accepts($jwt)) {
                $this->logger->debug('JWT not accepted by InstanceRegistryIssued parser');
                throw new Unauthenticated();
            }

            // Validate the token and determine the user
            $validatedUser = $this->jwtParser->determineUser($jwt);

            if ($validatedUser === null) {
                $this->logger->debug('JWT validation failed - no user determined');
                throw new Unauthenticated();
            }

            $this->logger->debug('JWT validation successful', [
                'user_id' => $validatedUser->getId(),
                'username' => $validatedUser->getUsername()
            ]);

            // Authorization successful - no exception thrown
        } catch (Rejected $e) {
            $this->logger->debug('JWT validation rejected', [
                'error' => $e->getMessage(),
                'code' => $e->getCode()
            ]);
            throw new Unauthenticated();
        } catch (\Exception $e) {
            $this->logger->error('Unexpected error during JWT validation', [
                'error' => $e->getMessage(),
                'code' => $e->getCode()
            ]);
            throw new Unauthenticated();
        }
    }

    /**
     * Get the Authorization header from the current request
     *
     * @return string|null
     */
    private function getAuthorizationHeader(): ?string
    {
        // Try different ways to get the Authorization header
        if (isset($_SERVER['HTTP_AUTHORIZATION'])) {
            return $_SERVER['HTTP_AUTHORIZATION'];
        }

        if (isset($_SERVER['REDIRECT_HTTP_AUTHORIZATION'])) {
            return $_SERVER['REDIRECT_HTTP_AUTHORIZATION'];
        }

        if (function_exists('apache_request_headers')) {
            $headers = apache_request_headers();
            if (isset($headers['Authorization'])) {
                return $headers['Authorization'];
            }
        }

        return null;
    }
}
